// Firma la petición a Convex con N8N_TO_CONVEX_SECRET.
const crypto = require('crypto');
const secret = $env.N8N_TO_CONVEX_SECRET;
if (!secret) throw new Error('N8N_TO_CONVEX_SECRET is not configured');

const payload = JSON.stringify({});
const timestamp = String(Math.floor(Date.now() / 1000));
const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.${payload}`).digest('hex');
return [{ json: { timestamp, signature, body: JSON.stringify({ payload }) } }];

// Un item por préstamo. Convex ya excluye los que recibieron recordatorio hoy.
const loans = $input.first().json.loans || [];
return loans.map((loan) => ({ json: loan }));

// Recordatorio simulado: se registra en el log de n8n.
// Para un email real, se buscaría el correo en Clerk con recipient.clerkUserId.
return $input.all().map(({ json: loan }) => {
  const reminder = {
    channel: 'log',
    loanId: loan.loanId,
    to: loan.recipient.name,
    message: loan.message,
    daysOverdue: loan.daysOverdue,
    sentAt: new Date().toISOString(),
  };
  console.log('[LendLoop overdue reminder]', JSON.stringify(reminder));
  return { json: { ...reminder, idempotencyKey: loan.idempotencyKey } };
});

// Firma el write-back para Convex con N8N_TO_CONVEX_SECRET.
const crypto = require('crypto');
const secret = $env.N8N_TO_CONVEX_SECRET;
if (!secret) throw new Error('N8N_TO_CONVEX_SECRET is not configured');

return $input.all().map(({ json }) => {
  const payload = JSON.stringify({
    loanId: json.loanId,
    type: 'overdue_reminder',
    status: 'sent',
    idempotencyKey: json.idempotencyKey,
    detail: `Reminded ${json.to} (${json.daysOverdue} day(s) overdue) via ${json.channel}`,
  });
  const timestamp = String(Math.floor(Date.now() / 1000));
  const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.${payload}`).digest('hex');
  return { json: { timestamp, signature, body: JSON.stringify({ payload }) } };
});
